#!/usr/bin/env python3

import psutil

def get_top_processes_by_memory(count=5):
    """Get top processes sorted by memory usage"""
    try:
        processes = []
        for proc in psutil.process_iter(['pid', 'name', 'memory_info']):
            try:
                # Get process info
                pid = proc.info['pid']
                name = proc.info['name']
                memory_mb = proc.info['memory_info'].rss / (1024 * 1024)  # Convert to MB

                processes.append({
                    'pid': pid,
                    'name': name,
                    'memory_mb': round(memory_mb, 2)
                })
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                # Process might have disappeared or we don't have access
                pass

        # Sort by memory usage (descending)
        processes.sort(key=lambda x: x['memory_mb'], reverse=True)
        return processes[:count]
    except Exception as e:
        return [{'error': str(e)}]

def main():
    # Get top 5 processes by memory usage
    top_processes = get_top_processes_by_memory(5)

    # Create report file
    with open('/workspace/top_processes.txt', 'w') as f:
        if len(top_processes) > 0 and 'error' in top_processes[0]:
            f.write(f"Error getting process info: {top_processes[0]['error']}\n")
            return

        for proc in top_processes:
            f.write(f"PID: {proc['pid']}, Name: {proc['name']}, Memory: {proc['memory_mb']} MB\n")

